//! Roc platform host: an HTTP server built on hyper + tower + matchit that
//! routes requests to handlers declared by the Roc app.
//!
//! `roc_platform_abi.rs` is generated by `roc glue` (see scripts/build-example.sh)
//! and must be regenerated whenever platform/main.roc changes.

#[allow(warnings)]
#[path = "roc_platform_abi.rs"]
mod abi;

mod body;
mod config;
mod effects;
mod middleware;
mod roc_call;
mod router;
mod server;
mod types;

use core::ffi::c_void;
use std::ptr;
use std::sync::OnceLock;

/// Host context for the generated helper functions (RocStr construction etc.).
/// Compiled Roc code does not see this; it calls the `roc_*` symbols directly.
fn roc_host() -> &'static abi::RocHost {
    static HOST: OnceLock<abi::RocHost> = OnceLock::new();
    HOST.get_or_init(|| abi::make_roc_host(ptr::null_mut()))
}

// SAFETY: the default allocator/handler function pointers are stateless and
// thread-safe; env is null and never dereferenced.
unsafe impl Sync for abi::RocHost {}
unsafe impl Send for abi::RocHost {}

// ---------------------------------------------------------------------------
// Direct symbol ABI required by compiled/interpreted Roc code.
// ---------------------------------------------------------------------------

#[unsafe(no_mangle)]
pub extern "C" fn roc_alloc(length: usize, alignment: usize) -> *mut c_void {
    abi::DefaultAllocators::roc_alloc(ptr::null_mut(), length, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_dealloc(ptr_: *mut c_void, alignment: usize) {
    abi::DefaultAllocators::roc_dealloc(ptr::null_mut(), ptr_, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_realloc(
    ptr_: *mut c_void,
    new_length: usize,
    alignment: usize,
) -> *mut c_void {
    abi::DefaultAllocators::roc_realloc(ptr::null_mut(), ptr_, new_length, alignment)
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_dbg(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    tracing::debug!(target: "roc", "{}", String::from_utf8_lossy(message));
}

#[unsafe(no_mangle)]
pub extern "C" fn roc_expect_failed(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    tracing::error!(target: "roc", "expect failed: {}", String::from_utf8_lossy(message));
}

/// Known limitation: `crash` in Roc code terminates the process. The erased
/// callable ABI gives the host no way to unwind out of a crashed interpreter
/// call, so a supervisor (systemd, container runtime) must restart the server.
/// Roc apps should return error responses instead of crashing.
#[unsafe(no_mangle)]
pub extern "C" fn roc_crashed(bytes: *const u8, len: usize) {
    let message = unsafe { core::slice::from_raw_parts(bytes, len) };
    tracing::error!(target: "roc", "crash: {}", String::from_utf8_lossy(message));
    eprintln!("[ROC CRASHED] {}", String::from_utf8_lossy(message));
    std::process::exit(1);
}

/// Process entrypoint. The Roc-built executable links this static library and
/// starts here.
#[unsafe(no_mangle)]
pub extern "C" fn main(_argc: i32, _argv: *const *const u8) -> i32 {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    // The runtime exists before any Roc code runs so that effects (outbound
    // HTTP) work from init! as well as from handlers.
    let runtime = match tokio::runtime::Builder::new_multi_thread().enable_all().build() {
        Ok(runtime) => runtime,
        Err(err) => {
            eprintln!("failed to start tokio runtime: {err}");
            return 1;
        }
    };
    effects::set_runtime(runtime.handle().clone());

    let app = match config::load_app() {
        Ok(app) => app,
        Err(err) => {
            eprintln!("invalid app configuration: {err}");
            return 1;
        }
    };

    let model = match roc_call::init_model() {
        Ok(model) => model,
        Err(message) => {
            eprintln!("init! failed: {message}");
            return 1;
        }
    };

    let router = match router::RocRouter::new(&app, model) {
        Ok(router) => router,
        Err(err) => {
            eprintln!("invalid route table: {err}");
            return 1;
        }
    };

    let service = match middleware::build_stack(router, &app.config) {
        Ok(service) => service,
        Err(err) => {
            eprintln!("invalid middleware configuration: {err}");
            return 1;
        }
    };

    server::run(runtime, service, app.config.port, app.routes.len())
}
